import redis.clients.jedis.JedisPooled; public class TestRedis { public static void main(String[] args) { try (JedisPooled p = new JedisPooled("localhost", 6379, "default", "redispassword")) { System.out.println("DEFAULT: " + p.ping()); } catch(Exception e) { System.out.println("DEFAULT ERROR: " + e.getMessage()); } try (JedisPooled p = new JedisPooled("localhost", 6379, null, "redispassword")) { System.out.println("NULL: " + p.ping()); } catch(Exception e) { System.out.println("NULL ERROR: " + e.getMessage()); } } }
